def transform(grid):
    # Collapse each consecutive run of identical rows, then identical columns.
    rows = []
    for row in grid:
        if not rows or row != rows[-1]:
            rows.append(row[:])
    out = []
    for j in range(len(rows[0])):
        col = [row[j] for row in rows]
        if j == 0 or col != prev:
            for i, value in enumerate(col):
                if j == 0:
                    if len(out) <= i:
                        out.append([])
                    out[i].append(value)
                else:
                    out[i].append(value)
        prev = col
    return out
